mapper.sql:
WHERE 1 = 1

    AND cancelled = FALSE
    AND departure_at > #{now}


    AND EXISTS (
        SELECT 1 FROM voyage_accepted_cargo_type t
        WHERE t.voyage_number = voyage.voyage_number
          AND t.cargo_type = #{criteria.cargoType}
    )



    AND departure_unlocode = #{criteria.departure}


    AND arrival_unlocode = #{criteria.arrival}


    AND departure_at >= #{criteria.departFrom}


    AND departure_at <= #{criteria.departTo}

mapper.insert:
INSERT INTO carrier_movement (
    voyage_number, movement_seq, departure_unlocode, arrival_unlocode,
    departure_at, arrival_at
) VALUES (
    #{voyageNumber}, #{movementSeq}, #{departureUnlocode}, #{arrivalUnlocode},
    #{departureAt}, #{arrivalAt}
)
ON CONFLICT (voyage_number, movement_seq) DO NOTHING

mapper.select:
SELECT * FROM voyage

ORDER BY departure_at, voyage_number
LIMIT #{limit} OFFSET #{offset}

SELECT cargo_type FROM voyage_accepted_cargo_type
WHERE voyage_number = #{voyageNumber}
ORDER BY cargo_type

SELECT * FROM carrier_movement
WHERE voyage_number = #{voyageNumber}
ORDER BY movement_seq
